 23→export const SendItemsList: FC<Props> = ({ roomId }) => {
 24→  const [isListOpen, setisListOpen] = useState(false);
 25→  const [isSending, setIsSending] = useState(false);
 26→  const [replyPayload, setReplyPayload] = useAtom(TimelineAtoms.replyPayload);
 27→
 28→  const handleCloseList = () => {
 29→    setisListOpen(false);
 30→  };
 31→
 32→  const handleOpenList = () => {
 33→    setisListOpen(true);
 34→    if (replyPayload) setReplyPayload(null);
 35→  };
 36→
 37→  const openImagePicker = async () => {
 38→    try {
 39→      setIsSending(true);
 40→      const response = await launchImageLibrary({
 41→        mediaType: "mixed",
 42→        selectionLimit: 3,
 43→        includeBase64: true,
 44→      });
 45→
 46→      if (!response.assets?.length) return;
 47→
 48→      handleCloseList();
 49→      // Delay to ensure the list is closed
 50→      setTimeout(() => {
 51→        if (!response.assets?.length) return;
 52→        NavigationContainerRef.navigate("sendImages", {
 53→          roomId,
 54→          images: response.assets,
 55→        });
 56→      }, 300);
 57→    } catch (error: unknown) {
 58→      Toast.show({
 59→        type: "error",
 60→        text1: "Failed to upload images",
 61→        text2: error instanceof Error ? error.message : "Unknown error",
 62→      });
 63→    } finally {
 64→      setIsSending(false);
 65→    }
 66→  };
 67→
 68→  const openCamera = async () => {
 69→    try {
 70→      setIsSending(true);
 71→      const response = await launchCamera({
 72→        mediaType: "photo",
 73→        includeBase64: true,
 74→      });
 75→
 76→      if (!response.assets?.length) return;
 77→
 78→      handleCloseList();
 79→      // Delay to ensure the list is closed
 80→      setTimeout(() => {
 81→        if (!response.assets?.length) return;
 82→        NavigationContainerRef.navigate("sendImages", {
 83→          roomId,
 84→          images: response.assets,
 85→        });
 86→      }, 300);
 87→    } catch (error: unknown) {
 88→      Toast.show({
 89→        type: "error",
 90→        text1: "Failed to take photo",
 91→        text2: error instanceof Error ? error.message : "Unknown error",
 92→      });
 93→    } finally {
 94→      setIsSending(false);
 95→    }
 96→  };
 97→
 98→  const openAttachment = async () => {
 99→    try {
100→      const result = await pick({
101→        mode: "open",
102→        allowMultiSelection: false,
103→      });
104→
105→      if (!result || result.length === 0) return;
106→
107→      const file = result[0];
108→      setIsSending(true);
109→      handleCloseList();
110→
111→      await MatrixService.sendAttachment(roomId, file);
112→
113→      Toast.show({
114→        type: "success",
115→        text1: "File sent successfully",
116→      });
117→    } catch (error: unknown) {
118→      // User cancelled the picker
119→      if (
120→        isErrorWithCode(error) &&
121→        error.code === errorCodes.OPERATION_CANCELED
122→      ) {
123→        return;
124→      }
125→
126→      console.error("Failed to send file:", error);
127→      Toast.show({
128→        type: "error",
129→        text1: "Failed to send file",
130→        text2: error instanceof Error ? error.message : "Unknown error",
131→      });
132→    } finally {
133→      setIsSending(false);
134→    }
135→  };
136→
137→  const list = useAnimateSequence(
138→    {
139→      opacity: [0, 1],
140→    },
141→    { duration: 200, easing: Easing.ease, native: false },
142→  );
143→
144→  useEffect(() => {
145→    if (isListOpen) list.start();
146→    else list.reverse();
147→  }, [isListOpen]);
148→
149→  return (
150→    <Block zIndex={2}>
151→      <Button.Outline
152→        style={styles.container}
153→        disabled={isSending}
154→        onPress={handleOpenList}
155→      >
156→        <Image
157→          source={require("assets/icons/plus.png")}
158→          style={styles.image}
159→          width={24}
160→          height={24}
161→        />
162→      </Button.Outline>
163→      <Modal visible={isListOpen} transparent={true} animationType="fade">
164→        <Block
165→          width="100%"
166→          height="100%"
167→          justify="flex-end"
168→          align="center"
169→          background={Colors.black70}
170→          paddings={[40, 20]}
171→        >
172→          {isSending && <Loading />}
173→          <Block width="100%" gap={8}>
174→            <Block
175→              width="100%"
176→              background={Colors.blackMinus3}
177→              border={{ borderRadius: 14 }}
178→            >
179→              <SingleSendItem
180→                title="Camera"
181→                image={require("assets/icons/camera.png")}
182→                onPress={openCamera}
183→                showSeparator
184→              />
185→              <SingleSendItem
186→                title="Photo & Video"
187→                image={require("assets/icons/image.png")}
188→                onPress={openImagePicker}
189→              />
190→              {/* <SingleSendItem
191→                title="Attachment"
192→                image={require("assets/icons/file-plus.png")}
193→                onPress={openAttachment}
194→              /> */}
195→            </Block>
196→            <Block
197→              width="100%"
198→              background={Colors.blackMinus3}
199→              border={{ borderRadius: 14 }}
200→            >
201→              <SingleSendItem title="Cancel" onPress={handleCloseList} />
202→            </Block>
203→          </Block>
204→        </Block>
205→      </Modal>
206→    </Block>
207→  );
208→};
