101→  /** Clear the crypto store directories to fix device ID mismatches */
102→  private static async clearCryptoStore() {
103→    try {
104→      const dataExists = await RNFS.exists(dataPath);
105→      const cacheExists = await RNFS.exists(cachePath);
106→
107→      if (dataExists) {
108→        await RNFS.unlink(dataPath);
109→        console.log("Cleared crypto data store");
110→      }
111→
112→      if (cacheExists) {
113→        await RNFS.unlink(cachePath);
114→        console.log("Cleared crypto cache store");
115→      }
116→    } catch (error) {
117→      console.warn("Failed to clear crypto store:", error);
118→    }
119→  }
120→
121→  /** Initialize client with error handling for RTC warnings */
122→  public static async initialize(serverUrl: string) {
123→    this.instance = await new ClientBuilder()
124→      .serverNameOrHomeserverUrl(serverUrl)
125→      .sessionPaths(dataPath, cachePath) // enables persistent stores (needed for E2EE)
126→      .autoEnableBackups(false)
127→      .build();
128→  }
