 26→/** Maximum age for a verification request to be considered valid (5 minutes) */
 27→const VERIFICATION_REQUEST_MAX_AGE_MS = 5 * 60 * 1000;
 28→
 29→/** Check if an event is a verification request */
 30→const isVerificationRequest = (event: EventTimelineItem): boolean => {
 31→  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return false;
 32→  const kind = event.content.inner.content.kind;
 33→  if (kind?.tag !== MsgLikeKind_Tags.Message) return false;
 34→  const msgType = kind.inner.content.msgType;
 35→  return (
 36→    msgType?.tag === MessageType_Tags.Other &&
 37→    msgType.inner.msgtype === "m.key.verification.request"
 38→  );
 39→};
 40→
 41→/** Check if a verification request is recent enough to be handled */
 42→const isRecentVerificationRequest = (event: EventTimelineItem): boolean => {
 43→  const eventTimestamp = Number(event.timestamp);
 44→  const now = Date.now();
 45→  const age = now - eventTimestamp;
 46→  return age < VERIFICATION_REQUEST_MAX_AGE_MS;
 47→};
