 56→  const [loadingMessage, setLoadingMessage] = useState(true);
 57→  /** Track processed verification request IDs to avoid duplicates */
 58→  const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
 59→  const [refreshing, setRefreshing] = useState(false);
 60→  const [updateTrigger, setUpdateTrigger] = useState(0);
